package main

// Deterministic no-show recovery projections. The input is generated by
// booking/recovery.py; every slot is future synthetic capacity, never the
// original provider Appointment and never a real cancellation.

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
	"time"
)

const (
	recoveryInputSchema = "wasl-recovery-input/1"
	recoverySchema      = "wasl-recovery/1"
	recoveryEventType   = "waitlist_recovery"
	recoveryConfirmKind = "confirm_backfill"
)

type recoverySlot struct {
	SlotID                   string `json:"slot_id"`
	BaseHead                 string `json:"base_head"`
	SourceFingerprint        string `json:"source_fingerprint"`
	Programme                string `json:"programme"`
	Procedure                string `json:"procedure"`
	Provider                 string `json:"provider"`
	SessionID                string `json:"session_id"`
	Unit                     string `json:"unit"`
	Region                   string `json:"region"`
	Day                      int    `json:"day"`
	Capacity                 int    `json:"capacity"`
	Booked                   int    `json:"booked,omitempty"`
	Regular                  bool   `json:"regular"`
	Overbooked               bool   `json:"overbooked"`
	Female                   bool   `json:"female"`
	Arabic                   bool   `json:"arabic"`
	AfterHours               bool   `json:"after_hours"`
	Ramadan                  bool   `json:"ramadan"`
	SourceCase               string `json:"source_case"`
	SourceAppointment        string `json:"source_appointment"`
	SourceDecisionSig        string `json:"source_decision_sig"`
	SourceAppointmentVersion int    `json:"source_appointment_version"`
	SourceBookingFingerprint string `json:"source_booking_fingerprint"`
	ProjectionBasis          string `json:"projection_basis"`
}

type recoveryWaitlistCase struct {
	CaseID                    string                 `json:"case_id"`
	Programme                 string                 `json:"programme"`
	State                     string                 `json:"state"`
	Provider                  string                 `json:"provider"`
	Priority                  string                 `json:"priority"`
	RequestedDay              int                    `json:"requested_day"`
	RepeatAfterUnsatisfactory bool                   `json:"repeat_after_unsatisfactory"`
	RepeatWindowLowerBound    int                    `json:"repeat_window_lower_bound"`
	DeadlineDay               int                    `json:"deadline_day"`
	Constraints               map[string]interface{} `json:"constraints"`
	Region                    string                 `json:"region"`
	PrepLead                  int                    `json:"prep_lead"`
	ExistingSuggestion        map[string]interface{} `json:"existing_suggestion"`
	SourceDecisionSig         string                 `json:"source_decision_sig"`
}

type recoveryInput struct {
	Schema           string                 `json:"schema"`
	DataMode         string                 `json:"data_mode"`
	DecisionSupport  bool                   `json:"decision_support_only"`
	Canonical        bool                   `json:"canonical_unchanged"`
	AsOfDay          int                    `json:"as_of_day"`
	Notice           string                 `json:"notice"`
	RankingPolicy    []string               `json:"ranking_policy"`
	Slots            []recoverySlot         `json:"slots"`
	Waitlist         []recoveryWaitlistCase `json:"waitlist"`
	InputFingerprint string                 `json:"input_fingerprint"`
}

type recoveryFill struct {
	SlotID     string
	CaseID     string
	EventHash  string
	Outreach   bool
	RequestID  string
	PayloadSHA string
	At         string
}

type recoveryProjection struct {
	Status   string
	Err      string
	Input    recoveryInput
	Slots    map[string]*recoverySlot
	Waitlist map[string]*recoveryWaitlistCase
	Fills    map[string]*recoveryFill
	ByCase   map[string]*recoveryFill
	Requests map[string]recoveryFill
}

func recoveryUnavailable(status, detail string) recoveryProjection {
	return recoveryProjection{Status: status, Err: detail, Slots: map[string]*recoverySlot{}, Waitlist: map[string]*recoveryWaitlistCase{},
		Fills: map[string]*recoveryFill{}, ByCase: map[string]*recoveryFill{}, Requests: map[string]recoveryFill{}}
}

func recoveryDigest(v interface{}) string {
	h := sha256.Sum256(canon(v))
	return hex.EncodeToString(h[:])
}

// recoverySlotSnapshot stores a JSON-object snapshot, not a typed struct. This
// keeps the ledger hash identical before marshalling and after replay.
func recoverySlotSnapshot(slot *recoverySlot) map[string]interface{} {
	raw, _ := json.Marshal(slot)
	var out map[string]interface{}
	_ = json.Unmarshal(raw, &out)
	return out
}

func recoverySlotID(slot recoverySlot) string {
	return "rel_" + recoveryDigest(map[string]interface{}{"sourceAppointment": slot.SourceAppointment,
		"sourceDecisionSig": slot.SourceDecisionSig, "session": slot.SessionID})[:24]
}

func recoveryBaseHead(slot recoverySlot) string {
	var generic map[string]interface{}
	raw, _ := json.Marshal(slot)
	_ = json.Unmarshal(raw, &generic)
	delete(generic, "base_head")
	delete(generic, "source_fingerprint")
	return recoveryDigest(generic)
}

func (s *apiServer) loadRecovery() {
	s.recovery = recoveryUnavailable("not_generated", "")
	path := filepath.Join(s.run, "recovery.json")
	raw, err := os.ReadFile(path)
	if err != nil {
		if !os.IsNotExist(err) {
			s.recovery = recoveryUnavailable("invalid", err.Error())
		}
		return
	}
	fail := func(err error) { s.recovery = recoveryUnavailable("invalid", err.Error()) }
	if err := rejectSemanticDuplicateKeys(raw); err != nil {
		fail(err)
		return
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	var in recoveryInput
	if err := dec.Decode(&in); err != nil {
		fail(err)
		return
	}
	if _, err := dec.Token(); err != io.EOF {
		fail(errors.New("trailing recovery input"))
		return
	}
	if in.Schema != recoveryInputSchema || in.DataMode != "simulated" || !in.DecisionSupport || !in.Canonical || in.AsOfDay < 0 {
		fail(errors.New("invalid recovery metadata"))
		return
	}
	fingerprint := in.InputFingerprint
	in.InputFingerprint = ""
	// The generator authenticates the object with this field absent, not empty.
	var generic map[string]interface{}
	if json.Unmarshal(raw, &generic) != nil {
		fail(errors.New("invalid recovery object"))
		return
	}
	delete(generic, "input_fingerprint")
	if fingerprint != recoveryDigest(generic) {
		fail(errors.New("recovery input fingerprint mismatch"))
		return
	}
	in.InputFingerprint = fingerprint
	p := recoveryUnavailable("ready", "")
	p.Input = in
	knownSourceDecision := func(c *apiCase, sig string) bool {
		if c == nil {
			return false
		}
		for _, decision := range c.decisions {
			if decision.Sig == sig {
				return true
			}
		}
		return false
	}
	for i := range in.Slots {
		slot := &in.Slots[i]
		if p.Slots[slot.SlotID] != nil || len(slot.SlotID) != 28 || !strings.HasPrefix(slot.SlotID, "rel_") || slot.SourceDecisionSig == "" || slot.SlotID != recoverySlotID(*slot) ||
			slot.BaseHead != recoveryBaseHead(*slot) || slot.SourceFingerprint == "" || slot.Capacity < 1 || slot.Booked < 0 || slot.Booked > slot.Capacity || !slot.Regular || slot.Overbooked ||
			(slot.Programme != "crc" && slot.Programme != "cervical") || slot.ProjectionBasis != "no_show_plus_future_synthetic_capacity_window" ||
			slot.Day <= in.AsOfDay || !knownSourceDecision(s.cases[slot.SourceCase], slot.SourceDecisionSig) {
			fail(fmt.Errorf("invalid or stale recovery slot %q", slot.SlotID))
			return
		}
		p.Slots[slot.SlotID] = slot
	}
	for i := range in.Waitlist {
		w := &in.Waitlist[i]
		if p.Waitlist[w.CaseID] != nil || s.cases[w.CaseID] == nil || s.cases[w.CaseID].Programme != w.Programme ||
			(w.Programme != "crc" && w.Programme != "cervical") || w.PrepLead < 0 || w.DeadlineDay < w.RequestedDay ||
			w.SourceDecisionSig == "" || !knownSourceDecision(s.cases[w.CaseID], w.SourceDecisionSig) {
			fail(fmt.Errorf("invalid recovery waitlist case %q", w.CaseID))
			return
		}
		p.Waitlist[w.CaseID] = w
	}
	s.recovery = p
}

func (s *apiServer) recoveryInputCurrentLocked() bool {
	raw, err := os.ReadFile(filepath.Join(s.run, "recovery.json"))
	if err != nil || rejectSemanticDuplicateKeys(raw) != nil {
		return false
	}
	var generic map[string]interface{}
	if json.Unmarshal(raw, &generic) != nil {
		return false
	}
	fingerprint, _ := generic["input_fingerprint"].(string)
	delete(generic, "input_fingerprint")
	return fingerprint == s.recovery.Input.InputFingerprint && recoveryDigest(generic) == fingerprint
}

func recoveryConstraintBool(w *recoveryWaitlistCase, key string) bool {
	v, _ := w.Constraints[key].(bool)
	return v
}

func recoveryConstraintString(w *recoveryWaitlistCase, key string) string {
	v, _ := w.Constraints[key].(string)
	return v
}

func (s *apiServer) recoverySlotStaleLocked(slot *recoverySlot) []string {
	reasons := []string{}
	source := s.cases[slot.SourceCase]
	if source == nil || source.last == nil || source.State != "no_show" || source.last.Sig != slot.SourceDecisionSig {
		reasons = append(reasons, "source_no_show_changed")
	}
	// A later Appointment version stales the release; absence in a sparse test
	// timeline is not treated as proof of a newer state.
	latestSeq := uint64(0)
	latestStatus := ""
	for _, fact := range s.facts[slot.SourceCase] {
		if fact["type"] == "Appointment" && fact["id"] == slot.SourceAppointment {
			seq, _ := fact["seq"].(uint64)
			if seq >= latestSeq {
				latestSeq, latestStatus = seq, fmt.Sprint(fact["status"])
			}
		}
	}
	if latestStatus != "" && latestStatus != "noshow" {
		reasons = append(reasons, "source_appointment_changed")
	}
	if slot.Day <= s.recovery.Input.AsOfDay {
		reasons = append(reasons, "past_slot")
	}
	return reasons
}

func (s *apiServer) recoverySessionCapacityAvailableLocked(slot *recoverySlot) bool {
	if slot == nil || slot.Booked < 0 || slot.Booked > slot.Capacity {
		return false
	}
	remaining := slot.Capacity - slot.Booked
	fills := 0
	for _, fill := range s.recovery.Fills {
		other := s.recovery.Slots[fill.SlotID]
		if other != nil && other.SessionID == slot.SessionID {
			fills++
			if fills >= remaining {
				return false
			}
		}
	}
	return remaining > 0
}

func recoveryOpenSlotHead(slot *recoverySlot) string {
	return recoveryDigest(map[string]interface{}{"base_head": slot.BaseHead, "status": "open", "filled_case": "", "event": ""})
}

func (s *apiServer) recoverySlotHeadLocked(slot *recoverySlot) string {
	status := "open"
	filled, event := "", ""
	if fill := s.recovery.Fills[slot.SlotID]; fill != nil {
		status, filled, event = "filled", fill.CaseID, fill.EventHash
	} else if stale := s.recoverySlotStaleLocked(slot); len(stale) > 0 {
		status = "stale"
	}
	return recoveryDigest(map[string]interface{}{"base_head": slot.BaseHead, "status": status, "filled_case": filled, "event": event})
}

func recoveryCheck(code, kind, result, reason string) map[string]interface{} {
	return map[string]interface{}{"code": code, "kind": kind, "result": result, "reason_code": reason}
}

func (s *apiServer) effectiveConsentLocked(c *apiCase) string {
	overlay, _ := s.overlayLocked(c)
	if status := fmt.Sprint(overlay["status"]); status != "none" && status != "" {
		return status
	}
	return consentFromDecision(c.last)
}

func recoverySecondIdentifierEvidenceAtDecision(c *apiCase, decision *Decision) []string {
	refs := []string{}
	for _, d := range c.decisions {
		if d != decision {
			continue // only the canonical decision current at confirmation
		}
		for _, outreach := range d.Outreach {
			guard := outreach.Guard == "dob_match" || outreach.Guard == "eid_match" || outreach.Guard == "human_path" || outreach.Guard == "human_confirmed"
			if outreach.Released && outreach.Suppress == "" && guard && strings.HasPrefix(outreach.Event, c.Provider+"/") {
				refs = append(refs, outreach.Event)
			}
		}
	}
	sort.Strings(refs)
	return refs
}

func (s *apiServer) recoverySecondIdentifierAtDecision(c *apiCase, decision *Decision) (bool, []string) {
	for _, item := range s.queue[c.ID] {
		if item.Reason == "second_identifier" {
			resolved := false
			for _, signoff := range s.signoffs[c.ID] {
				resolved = resolved || fmt.Sprint(signoff["item"]) == item.ItemID
			}
			if !resolved {
				return false, nil
			}
		}
	}
	refs := recoverySecondIdentifierEvidenceAtDecision(c, decision)
	return len(refs) > 0, refs
}

func (s *apiServer) recoverySecondIdentifierLocked(c *apiCase) (bool, []string) {
	return s.recoverySecondIdentifierAtDecision(c, c.last)
}

func (s *apiServer) recoveryOutreachLocked(c *apiCase) map[string]interface{} {
	consent := s.effectiveConsentLocked(c)
	second, refs := s.recoverySecondIdentifierLocked(c)
	reasons := []string{}
	if consent != "granted" {
		reasons = append(reasons, "consent_not_granted")
	}
	if !second {
		reasons = append(reasons, "second_identifier_unconfirmed")
	}
	secondStatus := "confirmed"
	if !second {
		secondStatus = "unconfirmed"
	}
	return map[string]interface{}{"allowed": consent == "granted" && second, "consent": consent,
		"second_identifier": secondStatus, "reason_codes": reasons, "guard_evidence": refs}
}

func (s *apiServer) recoveryCanonicalHoldLocked(c *apiCase) bool {
	for _, item := range s.queue[c.ID] {
		resolved := false
		for _, signoff := range s.signoffs[c.ID] {
			resolved = resolved || fmt.Sprint(signoff["item"]) == item.ItemID
		}
		if !resolved {
			return true
		}
	}
	return false
}

type recoveryReviewEvidence struct {
	status        string
	canonicalHold bool
}

func (s *apiServer) recoveryReviewEvidenceLocked(c *apiCase) recoveryReviewEvidence {
	return recoveryReviewEvidence{status: c.Review, canonicalHold: s.recoveryCanonicalHoldLocked(c)}
}

// recoveryReviewEvidenceFromEvent returns the hold state captured by the
// confirmation. Events written before this evidence was added can only have
// passed the write-side check with a non-open review and no unresolved hold.
func recoveryReviewEvidenceFromEvent(ev map[string]interface{}) (recoveryReviewEvidence, error) {
	statusValue, hasStatus := ev["review_at_confirmation"]
	holdValue, hasHold := ev["canonical_hold_at_confirmation"]
	if !hasStatus && !hasHold {
		return recoveryReviewEvidence{status: "none"}, nil
	}
	status, statusOK := statusValue.(string)
	hold, holdOK := holdValue.(bool)
	if !hasStatus || !hasHold || !statusOK || !holdOK || (status != "none" && status != "open" && status != "signed") {
		return recoveryReviewEvidence{}, errors.New("invalid recovery event-time review evidence")
	}
	return recoveryReviewEvidence{status: status, canonicalHold: hold}, nil
}

func (s *apiServer) recoveryCandidateLocked(slot *recoverySlot, w *recoveryWaitlistCase) map[string]interface{} {
	return s.recoveryCandidateAtDecisionLocked(slot, w, nil, "", nil)
}

// A non-nil guardDecision reconstructs the candidate at a historical ledger
// event. Source staleness and review holds are checked against stored event-time
// evidence, not against later canonical decisions, review items or sign-offs.
func (s *apiServer) recoveryCandidateAtDecisionLocked(slot *recoverySlot, w *recoveryWaitlistCase, guardDecision *Decision, replayCaseHead string, eventReview *recoveryReviewEvidence) map[string]interface{} {
	c := s.cases[w.CaseID]
	review := recoveryReviewEvidence{}
	if eventReview != nil {
		review = *eventReview
	} else {
		review = s.recoveryReviewEvidenceLocked(c)
	}
	if guardDecision != nil {
		historical := *c
		historical.last = guardDecision
		historical.Programme, historical.State, historical.Provider = guardDecision.Prog, guardDecision.State, guardDecision.Provider
		historical.Priority = guardDecision.Priority
		historical.Review = review.status
		historical.Closed = guardDecision.State == "closed" || guardDecision.State == "no_followup_needed" || guardDecision.State == "no_referral_needed" || guardDecision.State == "no_recall_needed"
		c = &historical
	}
	checks := []map[string]interface{}{}
	add := func(code, reason string, failed bool) {
		result, kind := "pass", "hard"
		if failed {
			result = "fail"
		}
		checks = append(checks, recoveryCheck(code, kind, result, reason))
	}
	unsupported := w.Programme != "crc" && w.Programme != "cervical"
	add("simulated_capacity", "no_simulated_capacity", unsupported)
	add("programme_match", "same_programme", w.Programme != slot.Programme)
	procedure := "colonoscopy"
	if w.Programme == "cervical" {
		procedure = "colposcopy"
	}
	add("procedure_match", "procedure_mismatch", procedure != slot.Procedure)
	active := c != nil && !c.Closed && c.Review != "open" && !review.canonicalHold && (c.State == "open" || c.State == "no_show" || c.State == "inadequate" || c.State == "referral_rejected")
	add("case_active", "case_closed_inactive_or_held", !active)
	add("not_source_case", "source_case_for_own_release", w.CaseID == slot.SourceCase)
	add("not_already_backfilled", "case_already_backfilled", s.recovery.ByCase[w.CaseID] != nil)
	stale := []string{}
	if guardDecision == nil {
		stale = s.recoverySlotStaleLocked(slot)
	}
	add("slot_current", "slot_stale_or_past", len(stale) > 0)
	add("prep_lead", "insufficient_prep_lead", slot.Day-s.recovery.Input.AsOfDay < w.PrepLead)
	add("repeat_window", "before_repeat_window", slot.Day < w.RepeatWindowLowerBound)
	add("region_match", "region_mismatch_without_travel", w.Region != slot.Region && !recoveryConstraintBool(w, "travel_ok"))
	add("female_requirement", "female_endoscopist_required", recoveryConstraintString(w, "female_endoscopist") == "hard" && !slot.Female)
	add("ramadan", "ramadan_conflict", recoveryConstraintBool(w, "avoid_ramadan") && slot.Ramadan)
	protected := slot.Female && recoveryConstraintString(w, "female_endoscopist") != "hard" && slot.Day-s.recovery.Input.AsOfDay > 7
	add("protected_female_capacity", "protected_female_list_outside_release_window", protected)
	add("regular_capacity", "non_regular_or_exhausted_capacity", !slot.Regular || slot.Overbooked || slot.Capacity < 1 || !s.recoverySessionCapacityAvailableLocked(slot))
	eligible := true
	for _, check := range checks {
		eligible = eligible && check["result"] == "pass"
	}
	if recoveryConstraintBool(w, "arabic_only") && !slot.Arabic {
		checks = append(checks, recoveryCheck("arabic_preference", "soft", "warning", "arabic_not_available"))
	}
	if recoveryConstraintBool(w, "after_hours") && !slot.AfterHours {
		checks = append(checks, recoveryCheck("after_hours_preference", "soft", "warning", "after_hours_not_available"))
	}
	if recoveryConstraintString(w, "female_endoscopist") == "soft" && !slot.Female {
		checks = append(checks, recoveryCheck("female_preference", "soft", "warning", "female_endoscopist_not_available"))
	}
	if slot.Day > w.DeadlineDay {
		checks = append(checks, recoveryCheck("deadline", "soft", "warning", "past_target"))
	}
	priorityRank := 1
	if strings.EqualFold(w.Priority, "urgent") || strings.EqualFold(c.Priority, "urgent") {
		priorityRank = 0
	}
	ordering := map[string]interface{}{"priority_rank": priorityRank, "deadline_day": w.DeadlineDay, "requested_day": w.RequestedDay, "tie_break": "case_id_ascending"}
	caseHead := s.caseHead(c)
	if guardDecision != nil {
		caseHead = replayCaseHead
	}
	candidate := map[string]interface{}{"case_id": w.CaseID, "eligible": eligible, "rank": nil, "priority": w.Priority,
		"requested_day": w.RequestedDay, "deadline_day": w.DeadlineDay, "constraints": w.Constraints, "checks": checks, "ordering": ordering,
		"case_head": caseHead}
	candidate["eligibility_hash"] = recoveryDigest(map[string]interface{}{"slot_base_head": slot.BaseHead, "candidate": candidate})
	candidate["outreach"] = s.recoveryOutreachLocked(c)
	return candidate
}

func recoveryCandidateLess(a, b map[string]interface{}) bool {
	if a["eligible"] != b["eligible"] {
		return a["eligible"] == true
	}
	ao, bo := a["ordering"].(map[string]interface{}), b["ordering"].(map[string]interface{})
	for _, key := range []string{"priority_rank", "deadline_day", "requested_day"} {
		if ao[key].(int) != bo[key].(int) {
			return ao[key].(int) < bo[key].(int)
		}
	}
	return fmt.Sprint(a["case_id"]) < fmt.Sprint(b["case_id"])
}

func (s *apiServer) recoveryCandidatesLocked(slot *recoverySlot) []map[string]interface{} {
	candidates := []map[string]interface{}{}
	for _, w := range s.recovery.Waitlist {
		candidates = append(candidates, s.recoveryCandidateLocked(slot, w))
	}
	sort.Slice(candidates, func(i, j int) bool { return recoveryCandidateLess(candidates[i], candidates[j]) })
	rank := 1
	for _, candidate := range candidates {
		if candidate["eligible"] == true {
			candidate["rank"] = rank
			rank++
		}
	}
	return candidates
}

func (s *apiServer) recoverySlotSummaryLocked(slot *recoverySlot) map[string]interface{} {
	status, filled := "open", ""
	reasons := s.recoverySlotStaleLocked(slot)
	if fill := s.recovery.Fills[slot.SlotID]; fill != nil {
		status, filled = "filled", fill.CaseID
	} else if len(reasons) > 0 {
		status = "stale"
	}
	return map[string]interface{}{"slot_id": slot.SlotID, "head": s.recoverySlotHeadLocked(slot), "status": status,
		"programme": slot.Programme, "procedure": slot.Procedure, "provider": slot.Provider, "unit": slot.Unit,
		"region": slot.Region, "day": slot.Day, "source_case": slot.SourceCase, "filled_case": filled, "stale_reason_codes": reasons}
}

func (s *apiServer) recoverySlotDetailLocked(slot *recoverySlot, viewer apiPrincipal) map[string]interface{} {
	out := s.recoverySlotSummaryLocked(slot)
	out["session_id"] = slot.SessionID
	out["capabilities"] = map[string]interface{}{"female": slot.Female, "arabic": slot.Arabic, "after_hours": slot.AfterHours, "ramadan": slot.Ramadan,
		"capacity": slot.Capacity, "booked": slot.Booked, "regular": slot.Regular, "overbooked": slot.Overbooked}
	out["release"] = map[string]interface{}{"source_case": slot.SourceCase, "source_appointment": slot.SourceAppointment,
		"source_decision_sig": slot.SourceDecisionSig, "source_appointment_version": slot.SourceAppointmentVersion,
		"source_booking_fingerprint": slot.SourceBookingFingerprint, "source_fingerprint": slot.SourceFingerprint,
		"projection_basis": slot.ProjectionBasis, "label": "simulated released-capacity projection"}
	out["base_head"] = slot.BaseHead
	out["candidates"] = s.recoveryCandidatesLocked(slot)
	out["backfill"] = nil
	out["outreach"] = map[string]interface{}{"status": "none", "dispatched": false}
	if fill := s.recovery.Fills[slot.SlotID]; fill != nil {
		out["backfill"] = map[string]interface{}{"case_id": fill.CaseID, "event": fill.EventHash, "at": fill.At, "status": "simulated_backfill_confirmed"}
		out["outreach"] = map[string]interface{}{"status": s.recoveryOutreachStatusLocked(fill), "dispatched": false}
	}
	history := []map[string]interface{}{}
	conc := s.concealedHashesLocked(viewer)
	for _, ev := range s.reviews {
		if ev["type"] == recoveryEventType && ev["slot"] == slot.SlotID {
			if shown, ok := viewerEvent(ev, conc); ok {
				history = append(history, shown)
			}
		}
	}
	out["history"] = history
	return out
}

func (s *apiServer) recoveryOutreachStatusLocked(fill *recoveryFill) string {
	if !fill.Outreach {
		return "none"
	}
	seen := false
	for _, ev := range s.reviews {
		if ev["hash"] == fill.EventHash {
			seen = true
			continue
		}
		if seen && ev["case"] == fill.CaseID && (ev["decision"] == "consent_denied" || ev["decision"] == "consent_opted_out") {
			return "cancelled_consent"
		}
	}
	if c := s.cases[fill.CaseID]; c != nil {
		if consent := s.effectiveConsentLocked(c); consent == "denied" || consent == "opted_out" {
			return "cancelled_consent"
		}
	}
	return "recorded_not_dispatched"
}

func (s *apiServer) recoveryCase(c *apiCase, viewer *apiPrincipal) map[string]interface{} {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.recoveryForCaseLocked(c, viewer)
}

func (s *apiServer) recoveryForCaseLocked(c *apiCase, viewer *apiPrincipal) map[string]interface{} {
	out := map[string]interface{}{"source_releases": []map[string]interface{}{}}
	releases := []map[string]interface{}{}
	for _, slot := range s.recovery.Slots {
		if slot.SourceCase == c.ID {
			releases = append(releases, s.recoverySlotSummaryLocked(slot))
		}
	}
	sort.Slice(releases, func(i, j int) bool { return fmt.Sprint(releases[i]["slot_id"]) < fmt.Sprint(releases[j]["slot_id"]) })
	out["source_releases"] = releases
	if fill := s.recovery.ByCase[c.ID]; fill != nil {
		slot := s.recovery.Slots[fill.SlotID]
		backfill := map[string]interface{}{"slot_id": fill.SlotID, "status": "simulated_backfill_confirmed", "day": slot.Day,
			"event": fill.EventHash, "outreach_status": s.recoveryOutreachStatusLocked(fill), "dispatched": false}
		if viewer != nil {
			conc := s.concealedHashesLocked(*viewer)
			if conc[fill.EventHash] {
				return out
			}
			// Never expose a concealed independent-read hash through event references.
			for _, ev := range s.reviews {
				if ev["hash"] == fill.EventHash {
					if shown, ok := viewerEvent(ev, conc); ok && shown["prev"] == nil {
						backfill["event"] = fill.EventHash
					}
				}
			}
		}
		out["backfill"] = backfill
	}
	return out
}

func (s *apiServer) recoveryListLocked(programme, status string, viewer apiPrincipal) map[string]interface{} {
	body := map[string]interface{}{"schema": recoverySchema, "status": s.recovery.Status, "data_mode": "simulated",
		"decision_support_only": true, "canonical_unchanged": true, "as_of_day": s.recovery.Input.AsOfDay,
		"ranking_policy": []string{"urgent_priority_first", "absolute_deadline_ascending", "requested_day_ascending", "case_id_ascending"},
		"slots":          []map[string]interface{}{}, "label": "simulated released-capacity projection"}
	if s.recovery.Status != "ready" {
		body["reason"] = s.recovery.Status
		if s.recovery.Err != "" {
			body["detail"] = s.recovery.Err
		}
		return body
	}
	if programme != "" && programme != "crc" && programme != "cervical" {
		body["reason"] = "no_simulated_capacity"
		return body
	}
	slots := []map[string]interface{}{}
	ids := []string{}
	for id := range s.recovery.Slots {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	for _, id := range ids {
		slot := s.recovery.Slots[id]
		summary := s.recoverySlotSummaryLocked(slot)
		if (programme == "" || programme == slot.Programme) && (status == "" || status == summary["status"]) {
			slots = append(slots, summary)
		}
	}
	body["slots"] = slots
	return body
}

// recoveryConsentBeforeLocked evaluates the consent overlay at the current
// replay position, before appending the recovery event itself.
func (s *apiServer) recoveryConsentBeforeLocked(c *apiCase, decision *Decision) string {
	status := consentFromDecision(decision)
	for _, prior := range s.reviews {
		if prior["case"] == c.ID && prior["action"] == ActRecordConsent {
			if next, ok := consentEvents[fmt.Sprint(prior["decision"])]; ok {
				status = next
			}
		}
	}
	return status
}

func stringsToInterface(values []string) []interface{} {
	out := make([]interface{}, len(values))
	for i, value := range values {
		out[i] = value
	}
	return out
}

// replayRecovery validates and applies one historical confirmation. It runs at
// the event's position in the shared ledger, so consent withdrawal cannot
// retroactively erase a valid earlier backfill, but does cancel its intent.
func (s *apiServer) replayRecovery(ev map[string]interface{}) error {
	if s.recovery.Status != "ready" {
		return fmt.Errorf("recovery event with %s recovery input", s.recovery.Status)
	}
	if ev["type"] != recoveryEventType || ev["kind"] != recoveryConfirmKind || ev["action"] != ActCoordinateCase || ev["mode"] != "demo" {
		return errors.New("invalid recovery event metadata")
	}
	role, actor := fmt.Sprint(ev["role"]), fmt.Sprint(ev["actor"])
	if !rbac[role][ActCoordinateCase] {
		return errors.New("recovery actor lacks coordinate_case")
	}
	if _, err := cleanText(actor, maxActorRunes, true, false); err != nil {
		return errors.New("invalid recovery actor")
	}
	if at, ok := ev["at"].(string); !ok {
		return errors.New("invalid recovery timestamp")
	} else if _, err := time.Parse(time.RFC3339Nano, at); err != nil {
		return errors.New("invalid recovery timestamp")
	}
	slot := s.recovery.Slots[fmt.Sprint(ev["slot"])]
	c := s.cases[fmt.Sprint(ev["case"])]
	if slot == nil || c == nil {
		return errors.New("recovery event for unknown slot or case")
	}
	w := s.recovery.Waitlist[c.ID]
	if w == nil {
		return errors.New("recovery event for case outside waitlist")
	}
	if ev["input_fingerprint"] != s.recovery.Input.InputFingerprint || ev["source_release_hash"] != slot.SourceFingerprint {
		return errors.New("recovery input or source release fingerprint changed")
	}
	sourceReleaseValid := false
	if source := s.cases[slot.SourceCase]; source != nil {
		for _, decision := range source.decisions {
			if decision.Sig == slot.SourceDecisionSig && decision.State == "no_show" {
				sourceReleaseValid = true
			}
		}
	}
	if !sourceReleaseValid {
		return errors.New("recovery source release evidence is not a canonical no-show")
	}
	guardDecisionSig, ok := ev["guard_decision_sig"].(string)
	if !ok || guardDecisionSig == "" {
		return errors.New("invalid recovery guard decision evidence")
	}
	var guardDecision *Decision
	for _, decision := range c.decisions {
		if decision.Sig == guardDecisionSig {
			guardDecision = decision
		}
	}
	if guardDecision == nil {
		return errors.New("recovery guard decision is not canonical evidence")
	}
	if snapshot, ok := ev["slot_snapshot"].(map[string]interface{}); !ok || !reflect.DeepEqual(snapshot, recoverySlotSnapshot(slot)) {
		return errors.New("recovery selected slot snapshot mismatch")
	}
	// Canonical cases are loaded at their final decision before ledger replay. Use
	// the hash-chained event evidence at this ledger position instead of applying
	// later source no-show or candidate decisions retroactively to this fill.
	expectedCaseHead := s.caseHead(c)
	if c.ov.head == "" {
		expectedCaseHead = guardDecision.Sig
	}
	if ev["expected_slot_head"] != recoveryOpenSlotHead(slot) || ev["expected_case_head"] != expectedCaseHead {
		return errors.New("recovery heads do not follow event-time evidence")
	}
	seq, ok := ev["seq"].(float64)
	if !ok || seq != float64(c.ov.n+1) {
		return errors.New("bad recovery per-case sequence")
	}
	if s.recovery.Fills[slot.SlotID] != nil || s.recovery.ByCase[c.ID] != nil {
		return errors.New("duplicate recovery slot or case fill")
	}
	if !s.recoverySessionCapacityAvailableLocked(slot) {
		return errors.New("recovery session capacity exceeded")
	}
	reviewEvidence, err := recoveryReviewEvidenceFromEvent(ev)
	if err != nil {
		return err
	}
	candidate := s.recoveryCandidateAtDecisionLocked(slot, w, guardDecision, expectedCaseHead, &reviewEvidence)
	if candidate["eligible"] != true || ev["eligibility_hash"] != candidate["eligibility_hash"] {
		return errors.New("recovery candidate does not match event-time eligibility evidence")
	}
	requestID, payloadSHA := fmt.Sprint(ev["request_id"]), fmt.Sprint(ev["payload_fingerprint"])
	if !validRecoveryRequestID(requestID) || payloadSHA == "" {
		return errors.New("invalid recovery idempotency data")
	}
	outreach, _ := ev["outreach_intent"].(bool)
	req := recoveryConfirmRequest{CaseID: c.ID, ExpectedSlotHead: fmt.Sprint(ev["expected_slot_head"]),
		ExpectedCaseHead: fmt.Sprint(ev["expected_case_head"]), RequestID: requestID, OutreachIntent: outreach, Note: fmt.Sprint(ev["note"])}
	if recoveryDigest(req) != payloadSHA {
		return errors.New("recovery payload fingerprint mismatch")
	}
	if old, exists := s.recovery.Requests[requestID]; exists {
		return fmt.Errorf("duplicate recovery request %s (original case %s)", requestID, old.CaseID)
	}
	if outreach {
		if ev["consent_at_confirmation"] != "granted" || s.recoveryConsentBeforeLocked(c, guardDecision) != "granted" {
			return errors.New("recovery outreach consent evidence not satisfied at event time")
		}
		refs := recoverySecondIdentifierEvidenceAtDecision(c, guardDecision)
		if len(refs) == 0 || !reflect.DeepEqual(ev["guard_evidence"], stringsToInterface(refs)) {
			return errors.New("recovery second-identifier evidence mismatch")
		}
	}
	s.reviews = append(s.reviews, ev)
	fill := &recoveryFill{SlotID: slot.SlotID, CaseID: c.ID, EventHash: fmt.Sprint(ev["hash"]), Outreach: outreach,
		RequestID: requestID, PayloadSHA: payloadSHA, At: fmt.Sprint(ev["at"])}
	s.recovery.Fills[slot.SlotID], s.recovery.ByCase[c.ID], s.recovery.Requests[requestID] = fill, fill, *fill
	c.ov.head, c.ov.lastAt = fmt.Sprint(ev["hash"]), fmt.Sprint(ev["at"])
	c.ov.n++
	return nil
}
